"use client"

import { ChangeEvent, FormEvent, useEffect, useMemo, useState } from "react"
import { Activity, ArrowUpRight, BriefcaseBusiness, CalendarClock, CalendarDays, CheckCircle2, ChevronRight, Clock3, FileText, FolderKanban, Loader2, Plus, RefreshCw, Search, ShieldCheck, UploadCloud, Wrench } from "lucide-react"

type Account={id:string;email:string;full_name:string|null;role:string}
type Client={id:string;user_id:string|null;company_name:string|null;status:string;created_at:string;profile:{full_name:string|null;email:string}|null}
type Project={id:string;client_id:string;name:string;description:string|null;status:string;deadline:string|null;created_at:string;updated_at:string|null}
type Service={id:string;client_id:string;project_id:string|null;customer_id:string;service_type:string;name:string;status:string;renews_at:string|null;currency:string|null}
type Milestone={id:string;project_id:string;title:string;description:string|null;status:string;due_at:string|null;sort_order:number}
type Deliverable={id:string;project_id:string;milestone_id:string|null;title:string;status:string;filename:string;created_at:string}
type ChangeRequest={id:string;project_id:string;customer_id:string;title:string;description:string;status:string;decision_note:string|null;created_at:string}
type Tab="client"|"project"|"service"|"milestone"|"deliverable"
type Data={clients:Client[];availableAccounts:Account[];projects:Project[];services:Service[];milestones:Milestone[];deliverables:Deliverable[];changeRequests:ChangeRequest[];servicesAvailable:boolean;milestonesAvailable:boolean;deliverablesAvailable:boolean;changeRequestsAvailable:boolean}
function date(value:string|null){if(!value)return "Not set";const parsed=new Date(value);return Number.isNaN(parsed.getTime())?"Not set":parsed.toLocaleDateString("en-ZM",{dateStyle:"medium"})}
function iso(value:string){return value?new Date(value).toISOString():null}

export default function AdminClientWorkspacePage(){
 const [data,setData]=useState<Data|null>(null)
 const [loading,setLoading]=useState(true)
 const [saving,setSaving]=useState(false)
 const [error,setError]=useState("")
 const [notice,setNotice]=useState("")
 const [tab,setTab]=useState<Tab>("client")
 const [accountId,setAccountId]=useState("")
 const [companyName,setCompanyName]=useState("")
 const [industry,setIndustry]=useState("")
 const [website,setWebsite]=useState("")
 const [clientId,setClientId]=useState("")
 const [projectId,setProjectId]=useState("")
 const [projectName,setProjectName]=useState("")
 const [projectCategory,setProjectCategory]=useState("brand_identity")
 const [projectDescription,setProjectDescription]=useState("")
 const [projectStatus,setProjectStatus]=useState("draft")
 const [projectDeadline,setProjectDeadline]=useState("")
 const [serviceType,setServiceType]=useState("maintenance")
 const [serviceName,setServiceName]=useState("")
 const [serviceDescription,setServiceDescription]=useState("")
 const [serviceStatus,setServiceStatus]=useState("active")
 const [serviceStart,setServiceStart]=useState("")
 const [serviceRenewal,setServiceRenewal]=useState("")
 const [currency,setCurrency]=useState("ZMW")
 const [milestoneTitle,setMilestoneTitle]=useState("")
 const [milestoneDescription,setMilestoneDescription]=useState("")
 const [milestoneStatus,setMilestoneStatus]=useState("pending")
 const [milestoneDue,setMilestoneDue]=useState("")
 const [milestoneOrder,setMilestoneOrder]=useState("0")
 const [deliverableTitle,setDeliverableTitle]=useState("")
 const [deliverableDescription,setDeliverableDescription]=useState("")
 const [deliverableMilestone,setDeliverableMilestone]=useState("")
 const [deliverableFile,setDeliverableFile]=useState<File|null>(null)
 const [showMilestoneEditor,setShowMilestoneEditor]=useState(false)
 const [showDeliverableEditor,setShowDeliverableEditor]=useState(false)
 const [editingTimeline,setEditingTimeline]=useState(false)
 const [timelineDeadline,setTimelineDeadline]=useState("")
 const [editingMilestoneId,setEditingMilestoneId]=useState("")

 async function load(){setLoading(true);setError("");try{const response=await fetch("/api/admin/client-workspace",{cache:"no-store"});const result=await response.json();if(!response.ok)throw new Error(result.error||"Workspace management data is unavailable.");const next=result as Data;setData(next);setClientId((current)=>current||next.clients[0]?.id||"");setProjectId((current)=>current||next.projects[0]?.id||"");setAccountId((current)=>current||next.availableAccounts[0]?.id||"")}catch(e){setError(e instanceof Error?e.message:"Workspace management data is unavailable.")}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 const clientProjects=useMemo(()=>data?.projects.filter((project)=>project.client_id===clientId)??[],[data,clientId])
 const projectMilestones=useMemo(()=>data?.milestones.filter((milestone)=>milestone.project_id===projectId)??[],[data,projectId])
 const clientName=(id:string)=>{const client=data?.clients.find((item)=>item.id===id);return client?.company_name||client?.profile?.full_name||client?.profile?.email||"Client not linked"}
 const projectNameFor=(id:string)=>data?.projects.find((item)=>item.id===id)?.name||"Project"
 const customerName=(id:string)=>{const client=data?.clients.find((item)=>item.user_id===id);return client?clientName(client.id):"Customer account"}

 async function post(body:Record<string,unknown>){setSaving(true);setError("");setNotice("");try{const response=await fetch("/api/admin/client-workspace",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const result=await response.json();if(!response.ok)throw new Error(result.error||"Could not save the record.");setNotice(result.message||"Saved.");if(result.client?.id)setClientId(result.client.id);if(result.project?.id){setProjectId(result.project.id);if(result.project.client_id)setClientId(result.project.client_id)}await load();return true}catch(e){setError(e instanceof Error?e.message:"Could not save the record.");return false}finally{setSaving(false)}}
 async function submitClient(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"create_client",userId:accountId,companyName,industry,website})){setCompanyName("");setIndustry("");setWebsite("")}}
 async function submitProject(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"create_project",clientId,category:projectCategory,name:projectName,description:projectDescription,status:projectStatus,deadline:iso(projectDeadline)})){setProjectName("");setProjectDescription("");setProjectDeadline("")}}
 async function submitService(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"create_service",clientId,projectId:projectId||null,serviceType,name:serviceName,description:serviceDescription,status:serviceStatus,startsAt:iso(serviceStart),renewsAt:iso(serviceRenewal),currency:currency||null})){setServiceName("");setServiceDescription("");setServiceRenewal("")}}
 async function submitMilestone(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"create_milestone",projectId,title:milestoneTitle,description:milestoneDescription,status:milestoneStatus,dueAt:iso(milestoneDue),sortOrder:Number(milestoneOrder)||0})){setMilestoneTitle("");setMilestoneDescription("");setMilestoneDue("");setMilestoneOrder(String((Number(milestoneOrder)||0)+1));setShowMilestoneEditor(false)}}
 async function submitTimeline(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"update_project_timeline",projectId,deadline:iso(timelineDeadline)}))setEditingTimeline(false)}
 async function submitMilestoneUpdate(event:FormEvent<HTMLFormElement>){event.preventDefault();if(await post({action:"update_milestone",milestoneId:editingMilestoneId,title:milestoneTitle,description:milestoneDescription,status:milestoneStatus,dueAt:iso(milestoneDue),sortOrder:Number(milestoneOrder)||0})){setEditingMilestoneId("");setMilestoneTitle("");setMilestoneDescription("");setMilestoneDue("");setShowMilestoneEditor(false)}}
 async function submitDeliverable(event:FormEvent<HTMLFormElement>){event.preventDefault();if(!deliverableFile)return;setSaving(true);setError("");setNotice("");try{const form=new FormData();form.set("projectId",projectId);if(deliverableMilestone)form.set("milestoneId",deliverableMilestone);form.set("title",deliverableTitle);form.set("description",deliverableDescription);form.set("file",deliverableFile);const response=await fetch("/api/admin/client-workspace/deliverables",{method:"POST",body:form});const result=await response.json();if(!response.ok)throw new Error(result.error||"Could not upload the deliverable.");setNotice(result.message||"Deliverable shared.");setDeliverableTitle("");setDeliverableDescription("");setDeliverableFile(null);setDeliverableMilestone("");setShowDeliverableEditor(false);const input=document.getElementById("admin-deliverable-file") as HTMLInputElement|null;if(input)input.value="";await load()}catch(e){setError(e instanceof Error?e.message:"Could not upload the deliverable.")}finally{setSaving(false)}}
 function changeTab(next:Tab){setTab(next);setError("");setNotice("")}

 const field="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-xs text-slate-800 outline-none focus:border-teal focus:ring-2 focus:ring-teal/15"
 const textarea="mt-1.5 w-full rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-xs leading-5 text-slate-800 outline-none focus:border-teal focus:ring-2 focus:ring-teal/15"
 const button="inline-flex h-10 items-center justify-center gap-2 rounded-xl bg-[#142239] px-4 text-xs font-semibold text-white hover:bg-[#203653] disabled:cursor-not-allowed disabled:opacity-50"

 return <div className="space-y-6">
  <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
   <div><p className="text-[10px] font-bold tracking-[0.17em] text-teal">CLIENT DELIVERY OPERATIONS</p><h1 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">Client workspace</h1><p className="mt-2 text-sm leading-6 text-slate-500">A live view of each client’s projects, deliverables and upcoming commitments.</p></div>
   <button onClick={()=>void load()} className="inline-flex h-10 items-center gap-2 self-start rounded-xl border border-slate-200 bg-white px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50"><RefreshCw className="h-3.5 w-3.5"/> Refresh data</button>
  </div>
  {error&&<p role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}
  {notice&&<p role="status" className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}
  <section className="rounded-2xl border border-slate-200 bg-white p-4 sm:p-5">
   <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
    <div><p className="text-xs font-bold text-slate-800">Select a client</p><p className="mt-1 text-[11px] text-slate-500">Everything below updates automatically for the selected client.</p></div>
    <div className="relative w-full sm:max-w-sm"><Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400"/><select aria-label="Select client" value={clientId} onChange={(e)=>{setClientId(e.target.value);setProjectId("")}} className="h-11 w-full appearance-none rounded-xl border border-slate-200 bg-white pl-9 pr-9 text-sm font-semibold text-slate-800 outline-none focus:border-teal focus:ring-2 focus:ring-teal/15"><option value="">Choose a client</option>{(data?.clients??[]).map((client)=><option key={client.id} value={client.id}>{clientName(client.id)}</option>)}</select><ChevronRight className="pointer-events-none absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 rotate-90 text-slate-400"/></div>
   </div>
  </section>
  {loading?<div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[1,2,3,4].map(i=><div key={i} className="h-24 animate-pulse rounded-2xl bg-slate-100"/>)}</div>:!clientId?<section className="rounded-2xl border border-dashed border-slate-300 bg-white p-12 text-center"><BriefcaseBusiness className="mx-auto h-8 w-8 text-slate-300"/><h2 className="mt-3 text-sm font-bold text-slate-800">Choose a client to get started</h2><p className="mt-1 text-xs text-slate-500">Select an existing client above to see their projects and delivery schedule.</p></section>:<>
   {(() => {
    const client=data?.clients.find(item=>item.id===clientId);
    const projects=clientProjects;
    const activeProjects=projects.filter(project=>!["completed","cancelled"].includes(project.status));
    const milestones=(data?.milestones??[]).filter(item=>projects.some(project=>project.id===item.project_id));
    const milestoneById=new Map(milestones.map(item=>[item.id,item]));
    const deliverables=(data?.deliverables??[]).filter(item=>projects.some(project=>project.id===item.project_id)&&!["approved","superseded","draft"].includes(item.status));
    const pendingMilestones=milestones.filter(item=>!["approved","completed"].includes(item.status)).sort((a,b)=>{if(!a.due_at)return 1;if(!b.due_at)return -1;return new Date(a.due_at).getTime()-new Date(b.due_at).getTime()});
    const upcoming=pendingMilestones.filter(item=>item.due_at).slice(0,6);
    const completedDeliverables=(data?.deliverables??[]).filter(item=>projects.some(project=>project.id===item.project_id)&&["approved"].includes(item.status)).length;
    const dueSoon=deliverables.filter(item=>{const due=milestoneById.get(item.milestone_id||"")?.due_at;return due&&new Date(due).getTime()>=Date.now()&&new Date(due).getTime()<=Date.now()+7*86400000}).length;
    const selectedProject=projects.find(item=>item.id===projectId);
    const timelineProjects=activeProjects.filter(item=>item.deadline).sort((a,b)=>new Date(a.created_at).getTime()-new Date(b.created_at).getTime());
    const timelineStart=timelineProjects.length?Math.min(Date.now(),...timelineProjects.map(item=>new Date(item.created_at).getTime())):Date.now();
    const timelineEnd=timelineProjects.length?Math.max(...timelineProjects.map(item=>new Date(item.deadline||item.created_at).getTime()),timelineStart+86400000):timelineStart+86400000;
    const span=Math.max(timelineEnd-timelineStart,86400000);
    return <>
     <section className="rounded-2xl border border-slate-200 bg-white p-5 sm:p-6">
      <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-wider text-teal">Client overview</p><h2 className="mt-1 text-xl font-extrabold text-slate-900">{clientName(clientId)}</h2><p className="mt-1 text-xs text-slate-500">{client?.profile?.email||"No linked email"} · Client since {date(client?.created_at||null)}</p></div><span className={"inline-flex w-fit items-center rounded-full px-3 py-1.5 text-[10px] font-bold "+(client?.status==="active"?"bg-emerald-50 text-emerald-700":"bg-slate-100 text-slate-600")}>{(client?.status||"unknown").replaceAll("_"," ")}</span></div>
      <div className="mt-5 grid gap-3 grid-cols-2 xl:grid-cols-4">
       {[{label:"Active projects",value:activeProjects.length,icon:FolderKanban,tone:"text-teal bg-teal/10"},{label:"Pending deliverables",value:deliverables.length,icon:FileText,tone:"text-violet-700 bg-violet-50"},{label:"Due in 7 days",value:dueSoon,icon:Clock3,tone:"text-amber-700 bg-amber-50"},{label:"Approved deliverables",value:completedDeliverables,icon:CheckCircle2,tone:"text-emerald-700 bg-emerald-50"}].map(card=>{const Icon=card.icon;return <div key={card.label} className="rounded-xl border border-slate-100 bg-slate-50/70 p-4"><div className="flex items-center justify-between"><span className="text-[11px] font-semibold text-slate-500">{card.label}</span><span className={"grid h-8 w-8 place-items-center rounded-lg "+card.tone}><Icon className="h-4 w-4"/></span></div><p className="mt-3 text-2xl font-extrabold tabular-nums text-slate-900">{card.value}</p></div>})}
      </div>
     </section>
     <section className="space-y-3"><div className="flex items-end justify-between"><div><h2 className="text-sm font-bold text-slate-900">Active projects</h2><p className="mt-1 text-[11px] text-slate-500">Select a project to inspect its milestones and delivery details.</p></div><span className="text-[10px] font-semibold text-slate-400">{activeProjects.length} active</span></div>
      {activeProjects.length?<div className="grid gap-3 lg:grid-cols-2">{activeProjects.map(project=>{const projectMilestones=milestones.filter(item=>item.project_id===project.id);const done=projectMilestones.filter(item=>["approved","completed"].includes(item.status)).length;const progress=projectMilestones.length?Math.round(done/projectMilestones.length*100):(project.status==="review"?90:project.status==="in_progress"?50:10);const next=projectMilestones.filter(item=>!["approved","completed"].includes(item.status)).sort((a,b)=>{if(!a.due_at)return 1;if(!b.due_at)return -1;return new Date(a.due_at).getTime()-new Date(b.due_at).getTime()})[0];return <button key={project.id} onClick={()=>setProjectId(project.id)} className={"rounded-2xl border p-4 text-left transition hover:border-teal/50 hover:shadow-sm "+(projectId===project.id?"border-teal bg-teal/[0.035]":"border-slate-200 bg-white")}><div className="flex items-start justify-between gap-3"><div className="min-w-0"><h3 className="truncate text-sm font-bold text-slate-900">{project.name}</h3><p className="mt-1 text-[10px] capitalize text-slate-500">{project.status.replaceAll("_"," ")}</p></div><ArrowUpRight className="h-4 w-4 shrink-0 text-slate-400"/></div><div className="mt-4 flex items-center justify-between text-[10px]"><span className="font-semibold text-slate-500">Milestone progress</span><span className="font-bold tabular-nums text-slate-800">{progress}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-slate-100"><div className="h-full rounded-full bg-teal" style={{width:progress+"%"}}/></div><div className="mt-3 flex flex-wrap items-center justify-between gap-2 text-[10px] text-slate-500"><span>Target {date(project.deadline)}</span><span>{next?"Next: "+next.title:"No pending milestones"}</span></div></button>})}</div>:<div className="rounded-xl border border-dashed border-slate-200 bg-white p-7 text-center text-xs text-slate-500">No active projects for this client.</div>}
     </section>
     {selectedProject&&<section className="rounded-2xl border border-teal/20 bg-white p-5 sm:p-6"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div><p className="text-[10px] font-bold uppercase tracking-wider text-teal">Project delivery controls</p><h3 className="mt-1 text-base font-extrabold text-slate-900">{selectedProject.name}</h3><p className="mt-1 text-xs text-slate-500">{selectedProject.description||"No project brief has been added."}</p><p className="mt-2 text-[10px] font-semibold text-slate-500">Target date: {date(selectedProject.deadline)}</p></div><div className="flex flex-wrap gap-2"><button onClick={()=>{setTimelineDeadline(selectedProject.deadline?selectedProject.deadline.slice(0,10):"");setEditingTimeline(v=>!v)}} className="rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-bold text-slate-700">Set timeline</button><button onClick={()=>{setEditingMilestoneId("");setMilestoneTitle("");setMilestoneDescription("");setMilestoneStatus("pending");setMilestoneDue("");setMilestoneOrder(String(milestones.filter(m=>m.project_id===selectedProject.id).length));setShowMilestoneEditor(v=>!v)}} className="rounded-lg bg-[#142239] px-3 py-2 text-[10px] font-bold text-white">Add milestone</button><button onClick={()=>{setProjectId(selectedProject.id);setShowDeliverableEditor(v=>!v)}} className="rounded-lg border border-teal/30 bg-teal/5 px-3 py-2 text-[10px] font-bold text-teal">Share deliverable</button><button onClick={()=>setProjectId("")} className="rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-semibold text-slate-600">Close</button></div></div>
 {editingTimeline&&<form onSubmit={submitTimeline} className="mt-4 flex flex-wrap items-end gap-3 rounded-xl bg-slate-50 p-4"><label className="min-w-[190px] flex-1"><span className="text-[10px] font-semibold text-slate-700">Project target date</span><input type="date" value={timelineDeadline} onChange={e=>setTimelineDeadline(e.target.value)} className={field}/></label><button disabled={saving} className={button}>Save timeline</button></form>}
 <div className="mt-5"><div className="mb-3 flex items-center justify-between"><h4 className="text-xs font-bold text-slate-800">Milestones and schedule</h4><span className="text-[10px] text-slate-400">{milestones.filter(m=>m.project_id===selectedProject.id).length} milestones</span></div><div className="space-y-2">{milestones.filter(item=>item.project_id===selectedProject.id).sort((a,b)=>a.sort_order-b.sort_order).map(item=><div key={item.id} className="rounded-xl border border-slate-100 bg-slate-50/70 p-3"><div className="flex flex-wrap items-start justify-between gap-3"><div className="min-w-0"><p className="text-xs font-semibold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{item.status.replaceAll("_"," ")} · Due {date(item.due_at)}</p>{item.description&&<p className="mt-1 text-[10px] leading-4 text-slate-500">{item.description}</p>}</div><button onClick={()=>{setEditingMilestoneId(item.id);setMilestoneTitle(item.title);setMilestoneDescription(item.description||"");setMilestoneStatus(item.status);setMilestoneDue(item.due_at?item.due_at.slice(0,10):"");setMilestoneOrder(String(item.sort_order));setShowMilestoneEditor(true)}} className="rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-[10px] font-bold text-slate-600">Edit</button></div></div>)}{!milestones.some(item=>item.project_id===selectedProject.id)&&<p className="rounded-xl border border-dashed border-slate-200 p-5 text-center text-xs text-slate-500">No milestones yet. Add the first milestone to build this project’s schedule.</p>}</div></div>
 {showMilestoneEditor&&<form onSubmit={editingMilestoneId?submitMilestoneUpdate:submitMilestone} className="mt-4 grid gap-3 rounded-xl border border-teal/20 bg-teal/[0.025] p-4 sm:grid-cols-2"><div className="sm:col-span-2"><h4 className="text-xs font-bold text-slate-800">{editingMilestoneId?"Update milestone":"New milestone"}</h4></div><label className="sm:col-span-2"><span className="text-[10px] font-semibold text-slate-700">Milestone title</span><input required minLength={2} maxLength={180} value={milestoneTitle} onChange={e=>setMilestoneTitle(e.target.value)} className={field}/></label><label className="sm:col-span-2"><span className="text-[10px] font-semibold text-slate-700">Description</span><textarea rows={2} maxLength={2000} value={milestoneDescription} onChange={e=>setMilestoneDescription(e.target.value)} className={textarea}/></label><label><span className="text-[10px] font-semibold text-slate-700">Status</span><select value={milestoneStatus} onChange={e=>setMilestoneStatus(e.target.value)} className={field}><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="ready_for_review">Ready for review</option><option value="blocked">Blocked</option><option value="completed">Completed</option><option value="approved">Approved</option></select></label><label><span className="text-[10px] font-semibold text-slate-700">Due date</span><input type="date" value={milestoneDue} onChange={e=>setMilestoneDue(e.target.value)} className={field}/></label><label><span className="text-[10px] font-semibold text-slate-700">Order</span><input type="number" min="0" max="10000" value={milestoneOrder} onChange={e=>setMilestoneOrder(e.target.value)} className={field}/></label><div className="flex items-end gap-2"><button disabled={saving} className={button}>{saving?"Saving…":editingMilestoneId?"Save changes":"Add milestone"}</button><button type="button" onClick={()=>{setShowMilestoneEditor(false);setEditingMilestoneId("")}} className="h-10 rounded-xl border border-slate-200 px-3 text-[10px] font-semibold text-slate-600">Cancel</button></div></form>}
 {showDeliverableEditor&&<form onSubmit={submitDeliverable} className="mt-4 grid gap-3 rounded-xl border border-violet-100 bg-violet-50/30 p-4 sm:grid-cols-2"><div className="sm:col-span-2"><h4 className="text-xs font-bold text-slate-800">Share a deliverable with the client</h4><p className="mt-1 text-[10px] text-slate-500">The file will appear in the customer portal.</p></div><label><span className="text-[10px] font-semibold text-slate-700">Related milestone</span><select value={deliverableMilestone} onChange={e=>setDeliverableMilestone(e.target.value)} className={field}><option value="">Not tied to a milestone</option>{milestones.filter(m=>m.project_id===selectedProject.id).map(m=><option key={m.id} value={m.id}>{m.title}</option>)}</select></label><label><span className="text-[10px] font-semibold text-slate-700">Deliverable title</span><input required minLength={2} maxLength={180} value={deliverableTitle} onChange={e=>setDeliverableTitle(e.target.value)} className={field} placeholder="e.g. Homepage design v1"/></label><label className="sm:col-span-2"><span className="text-[10px] font-semibold text-slate-700">Description</span><textarea rows={2} maxLength={2000} value={deliverableDescription} onChange={e=>setDeliverableDescription(e.target.value)} className={textarea}/></label><label className="sm:col-span-2"><span className="text-[10px] font-semibold text-slate-700">File</span><input id="admin-deliverable-file" type="file" required onChange={(e:ChangeEvent<HTMLInputElement>)=>setDeliverableFile(e.target.files?.[0]??null)} accept=".png,.jpg,.jpeg,.webp,.svg,.pdf,.zip,.txt,.md,.json,.bin" className="mt-1.5 block w-full rounded-xl border border-slate-200 px-3 py-3 text-[10px] file:mr-3 file:rounded-lg file:border-0 file:bg-slate-100 file:px-3 file:py-2 file:text-[10px] file:font-bold"/></label><div className="flex items-end gap-2"><button disabled={saving||!data?.deliverablesAvailable||!deliverableFile} className={button}>{saving?"Uploading…":"Upload and share"}</button><button type="button" onClick={()=>setShowDeliverableEditor(false)} className="h-10 rounded-xl border border-slate-200 px-3 text-[10px] font-semibold text-slate-600">Cancel</button></div></form>}
 </section>}
     <div className="grid items-start gap-4 xl:grid-cols-[minmax(0,1.15fr)_minmax(300px,0.85fr)]">
      <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-slate-900">Pending deliverables</h2><p className="mt-1 text-[11px] text-slate-500">Outstanding client work and its associated milestone due date.</p></div><FileText className="h-4 w-4 text-slate-400"/></div>
       <div className="mt-4 divide-y divide-slate-100">{deliverables.sort((a,b)=>{const ad=milestoneById.get(a.milestone_id||"")?.due_at;const bd=milestoneById.get(b.milestone_id||"")?.due_at;if(!ad)return 1;if(!bd)return -1;return new Date(ad).getTime()-new Date(bd).getTime()}).map(item=>{const due=milestoneById.get(item.milestone_id||"")?.due_at;const overdue=due&&new Date(due).getTime()<Date.now();return <div key={item.id} className="flex items-start justify-between gap-3 py-3"><div className="min-w-0"><p className="truncate text-xs font-bold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{projectNameFor(item.project_id)} · {item.status.replaceAll("_"," ")}</p></div><div className="shrink-0 text-right"><p className={"text-[10px] font-bold "+(overdue?"text-rose-600":"text-slate-700")}>{due?date(due):"No due date"}</p>{overdue&&<p className="mt-0.5 text-[9px] font-bold text-rose-600">Overdue</p>}</div></div>})}{!deliverables.length&&<p className="py-6 text-center text-xs text-slate-500">No pending deliverables.</p>}</div>
      </section>
      <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-slate-900">Upcoming milestones</h2><p className="mt-1 text-[11px] text-slate-500">Next scheduled project commitments.</p></div><CalendarDays className="h-4 w-4 text-slate-400"/></div><div className="mt-4 space-y-3">{upcoming.map(item=>{const overdue=new Date(item.due_at!).getTime()<Date.now();return <div key={item.id} className="flex gap-3"><div className="flex w-11 shrink-0 flex-col items-center rounded-lg bg-slate-50 py-2"><span className="text-[9px] font-bold uppercase text-slate-400">{new Date(item.due_at!).toLocaleDateString("en-ZM",{month:"short"})}</span><span className="text-sm font-extrabold text-slate-800">{new Date(item.due_at!).getDate()}</span></div><div className="min-w-0 flex-1 border-b border-slate-100 pb-3"><p className="text-xs font-semibold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{projectNameFor(item.project_id)} · {item.status.replaceAll("_"," ")}</p>{overdue&&<p className="mt-1 text-[9px] font-bold text-rose-600">Past due</p>}</div></div>})}{!upcoming.length&&<p className="py-6 text-center text-xs text-slate-500">No dated upcoming milestones.</p>}</div></section>
     </div>
     <section className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between"><div><h2 className="text-sm font-bold text-slate-900">Project timeline</h2><p className="mt-1 text-[11px] text-slate-500">A consolidated view of active project schedules and target dates.</p></div><Activity className="h-4 w-4 text-slate-400"/></div>
      {timelineProjects.length?<div className="mt-5 space-y-4"><div className="ml-[130px] flex justify-between text-[9px] text-slate-400"><span>{new Date(timelineStart).toLocaleDateString("en-ZM",{month:"short",day:"numeric"})}</span><span>Today</span><span>{new Date(timelineEnd).toLocaleDateString("en-ZM",{month:"short",day:"numeric"})}</span></div>{timelineProjects.map(project=>{const start=Math.max(0,(new Date(project.created_at).getTime()-timelineStart)/span*100);const end=Math.min(100,Math.max(start+2,(new Date(project.deadline!).getTime()-timelineStart)/span*100));return <div key={project.id} className="grid grid-cols-[118px_minmax(0,1fr)] items-center gap-3"><p className="truncate text-[10px] font-semibold text-slate-600">{project.name}</p><div className="relative h-7 rounded-lg bg-slate-50"><div className="absolute top-1.5 h-4 rounded-md bg-teal/80" style={{left:start+"%",width:Math.max(2,end-start)+"%"}}/><div className="absolute inset-y-0 border-l border-dashed border-slate-300" style={{left:Math.max(0,Math.min(100,(Date.now()-timelineStart)/span*100))+"%"}}/></div></div>})}</div>:<p className="mt-5 rounded-xl bg-slate-50 p-6 text-center text-xs text-slate-500">Add target dates to active projects to see them on the timeline.</p>}
     </section>
    </>;
   })()}
  </>}
  <details className="group rounded-2xl border border-slate-200 bg-white">
   <summary className="flex cursor-pointer list-none items-center justify-between gap-3 p-5"><div><h2 className="text-sm font-bold text-slate-900">Manage client records</h2><p className="mt-1 text-[11px] text-slate-500">Create clients, projects, services, milestones and upload deliverables when needed.</p></div><span className="rounded-lg border border-slate-200 px-3 py-2 text-[10px] font-bold text-slate-600 group-open:bg-slate-50">Open management tools</span></summary>
   <div className="border-t border-slate-100 p-4 sm:p-5"><div className="space-y-6">
  <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-[10px] font-bold tracking-[0.17em] text-teal">CLIENT DELIVERY OPERATIONS</p><h1 className="mt-2 text-2xl font-extrabold tracking-tight text-slate-900 sm:text-3xl">Client workspace</h1><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-500">Create client projects, assign ongoing services, publish milestones and share private deliverables that appear in the customer portal.</p></div><button onClick={()=>void load()} className="inline-flex h-10 items-center gap-2 self-start rounded-xl border border-slate-200 bg-white px-3 text-xs font-semibold text-slate-600 hover:bg-slate-50"><RefreshCw className="h-3.5 w-3.5"/> Refresh</button></div>
  {error&&<p role="alert" className="rounded-xl border border-rose-200 bg-rose-50 p-3 text-sm text-rose-800">{error}</p>}{notice&&<p role="status" className="rounded-xl border border-emerald-200 bg-emerald-50 p-3 text-sm text-emerald-800">{notice}</p>}
  {data&&(!data.servicesAvailable||!data.milestonesAvailable||!data.deliverablesAvailable||!data.changeRequestsAvailable)&&<div className="flex items-start gap-3 rounded-xl border border-amber-200 bg-amber-50 p-4"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-amber-700"/><div><p className="text-xs font-bold text-amber-950">Workspace schema migration pending in this environment</p><p className="mt-1 text-xs leading-5 text-amber-900">Projects can be created using the existing schema. Service records, milestones, deliverables and change-request review require the client portal migration before those actions can be saved. No live database migration has been applied by this feature branch.</p></div></div>}
  <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[{label:"Clients",value:data?.clients.length??"—",icon:BriefcaseBusiness},{label:"Projects",value:data?.projects.length??"—",icon:FolderKanban},{label:"Services",value:data?.servicesAvailable?data.services.length:"—",icon:Wrench},{label:"Deliverables",value:data?.deliverablesAvailable?data.deliverables.length:"—",icon:FileText}].map((card)=>{const Icon=card.icon;return <div key={card.label} className="rounded-2xl border border-slate-200 bg-white p-4"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-slate-500">{card.label}</span><Icon className="h-4 w-4 text-teal"/></div><p className="mt-3 text-2xl font-extrabold text-slate-900">{loading?"—":card.value}</p></div>})}</div>
  <div className="grid items-start gap-5 xl:grid-cols-[minmax(0,1.05fr)_minmax(340px,0.95fr)]">
   <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="border-b border-slate-100 px-5 py-4"><h2 className="text-sm font-bold text-slate-800">Delivery records</h2><p className="mt-1 text-xs text-slate-500">Current projects, services, milestones and shared files.</p></div>
    {loading?<div className="space-y-3 p-5"><div className="h-14 animate-pulse rounded-xl bg-slate-100"/><div className="h-14 animate-pulse rounded-xl bg-slate-100"/></div>:<div className="divide-y divide-slate-100">
     {(data?.projects??[]).slice(0,10).map((project)=><div key={project.id} className="flex items-start gap-3 p-4"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-teal/10 text-teal"><FolderKanban className="h-4 w-4"/></span><div className="min-w-0 flex-1"><p className="text-xs font-bold text-slate-800">{project.name}</p><p className="mt-1 text-[10px] text-slate-500">{clientName(project.client_id)} · {project.status.replaceAll("_"," ")} · Due {date(project.deadline)}</p></div><button onClick={()=>{setProjectId(project.id);setClientId(project.client_id);changeTab("milestone")}} className="shrink-0 rounded-lg border border-slate-200 px-2.5 py-2 text-[10px] font-semibold text-slate-600 hover:bg-slate-50">Manage</button></div>)}
     {!data?.projects.length&&<p className="p-6 text-center text-xs text-slate-500">No projects yet. Create the first project using the form.</p>}
     {(data?.services??[]).slice(0,5).map((service)=><div key={service.id} className="flex items-start gap-3 p-4"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-blue-50 text-blue-700"><Wrench className="h-4 w-4"/></span><div className="min-w-0 flex-1"><p className="text-xs font-bold text-slate-800">{service.name}</p><p className="mt-1 text-[10px] text-slate-500">{clientName(service.client_id)} · {service.status} · Renewal {date(service.renews_at)}</p></div></div>)}
     {(data?.deliverables??[]).slice(0,5).map((item)=><div key={item.id} className="flex items-start gap-3 p-4"><span className="grid h-9 w-9 shrink-0 place-items-center rounded-xl bg-violet-50 text-violet-700"><FileText className="h-4 w-4"/></span><div className="min-w-0 flex-1"><p className="text-xs font-bold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{projectNameFor(item.project_id)} · {item.status} · {item.filename}</p></div></div>)}
     {(data?.changeRequests??[]).slice(0,10).map((item)=><div key={item.id} className="border-t border-slate-100 p-4"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="text-xs font-bold text-slate-800">{item.title}</p><p className="mt-1 text-[10px] text-slate-500">{projectNameFor(item.project_id)} · {customerName(item.customer_id)} · {item.status.replaceAll("_"," ")}</p></div><span className="rounded-full bg-amber-50 px-2 py-1 text-[9px] font-bold text-amber-800">Change request</span></div><p className="mt-2 line-clamp-2 text-[10px] leading-5 text-slate-500">{item.description}</p>{!["completed","declined"].includes(item.status)&&<div className="mt-3 flex flex-wrap gap-2"><button disabled={saving||!data?.changeRequestsAvailable} onClick={()=>void post({action:"review_change_request",changeRequestId:item.id,status:"under_review",decisionNote:""})} className="rounded-lg border border-slate-200 px-2.5 py-1.5 text-[9px] font-bold text-slate-600 hover:bg-slate-50">Mark in review</button><button disabled={saving||!data?.changeRequestsAvailable} onClick={()=>void post({action:"review_change_request",changeRequestId:item.id,status:"approved",decisionNote:"Approved for review and scoping."})} className="rounded-lg bg-emerald-600 px-2.5 py-1.5 text-[9px] font-bold text-white disabled:opacity-50">Approve</button><button disabled={saving||!data?.changeRequestsAvailable} onClick={()=>void post({action:"review_change_request",changeRequestId:item.id,status:"declined",decisionNote:"This request needs a discussion with the client before proceeding."})} className="rounded-lg bg-rose-600 px-2.5 py-1.5 text-[9px] font-bold text-white disabled:opacity-50">Decline</button></div>}</div>)}
    </div>}
   </section>
   <section className="overflow-hidden rounded-2xl border border-slate-200 bg-white"><div className="grid grid-cols-2 border-b border-slate-100 sm:grid-cols-3 xl:grid-cols-5">{([{key:"client",label:"Client",icon:BriefcaseBusiness},{key:"project",label:"Project",icon:FolderKanban},{key:"service",label:"Service",icon:Wrench},{key:"milestone",label:"Milestone",icon:CalendarClock},{key:"deliverable",label:"Deliverable",icon:UploadCloud}] as const).map((item)=>{const Icon=item.icon;return <button key={item.key} onClick={()=>changeTab(item.key)} className={"flex min-h-16 flex-col items-center justify-center gap-1.5 border-b-2 px-2 py-3 text-[10px] font-bold "+(tab===item.key?"border-teal bg-teal/5 text-slate-900":"border-transparent text-slate-500 hover:bg-slate-50")}><Icon className="h-4 w-4"/>{item.label}</button>})}</div>
    <div className="p-5 sm:p-6">
     {tab==="client"&&<form onSubmit={submitClient} className="space-y-4"><div><h3 className="text-sm font-bold text-slate-800">Create a client workspace</h3><p className="mt-1 text-xs text-slate-500">Link an existing non-admin account to a client record. Accounts must register before they can be linked.</p></div><label className="block"><span className="text-xs font-semibold text-slate-700">Existing customer account</span><select required value={accountId} onChange={(e)=>setAccountId(e.target.value)} className={field}><option value="">Choose an account</option>{(data?.availableAccounts??[]).map((account)=><option key={account.id} value={account.id}>{account.full_name?account.full_name+" — ":""}{account.email}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Company or client name</span><input required minLength={2} maxLength={180} value={companyName} onChange={(e)=>setCompanyName(e.target.value)} className={field} placeholder="e.g. Apex Trail Gear"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Industry (optional)</span><input maxLength={120} value={industry} onChange={(e)=>setIndustry(e.target.value)} className={field} placeholder="e.g. Retail, education, healthcare"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Website (optional)</span><input maxLength={255} value={website} onChange={(e)=>setWebsite(e.target.value)} className={field} placeholder="https://example.com"/></label><button disabled={saving||!accountId} className={button}>{saving?<Loader2 className="h-4 w-4 animate-spin"/>:<Plus className="h-4 w-4"/>} Create client workspace</button>{!data?.availableAccounts.length&&<p className="text-[10px] leading-5 text-amber-800">No eligible customer accounts were found. The customer must register before you can link a workspace.</p>}</form>}
     {tab==="project"&&<form onSubmit={submitProject} className="space-y-4"><div><h3 className="text-sm font-bold text-slate-800">Create a project</h3><p className="mt-1 text-xs text-slate-500">Projects can cover creative, digital or technical engagements.</p></div><label className="block"><span className="text-xs font-semibold text-slate-700">Client</span><select required value={clientId} onChange={(e)=>setClientId(e.target.value)} className={field}><option value="">Choose a client</option>{(data?.clients??[]).map((client)=><option key={client.id} value={client.id}>{clientName(client.id)}{client.user_id?"":" (not linked to login)"}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Project name</span><input required minLength={2} maxLength={160} value={projectName} onChange={(e)=>setProjectName(e.target.value)} className={field} placeholder="e.g. Brand identity refresh"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Service category</span><select value={projectCategory} onChange={(e)=>setProjectCategory(e.target.value)} className={field}><option value="brand_identity">Brand identity</option><option value="graphic_design">Graphic design</option><option value="website">Website</option><option value="web_application">Web application</option><option value="mobile_app">Mobile application</option><option value="software">Software development</option><option value="ui_ux">UI/UX design</option><option value="custom">Custom / other</option></select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Brief / description</span><textarea maxLength={4000} rows={3} value={projectDescription} onChange={(e)=>setProjectDescription(e.target.value)} className={textarea} placeholder="Scope, goals and relevant context."/></label><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="text-xs font-semibold text-slate-700">Initial status</span><select value={projectStatus} onChange={(e)=>setProjectStatus(e.target.value)} className={field}><option value="draft">Draft</option><option value="in_progress">In progress</option><option value="review">In review</option></select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Target date (optional)</span><input type="date" value={projectDeadline} onChange={(e)=>setProjectDeadline(e.target.value)} className={field}/></label></div><button disabled={saving||!clientId} className={button}>{saving?<Loader2 className="h-4 w-4 animate-spin"/>:<Plus className="h-4 w-4"/>} Create project</button></form>}
     {tab==="service"&&<form onSubmit={submitService} className="space-y-4"><div><h3 className="text-sm font-bold text-slate-800">Assign a service</h3><p className="mt-1 text-xs text-slate-500">Create an ongoing service record linked to a customer account.</p></div><label className="block"><span className="text-xs font-semibold text-slate-700">Client</span><select required value={clientId} onChange={(e)=>{setClientId(e.target.value);setProjectId("")}} className={field}><option value="">Choose a client</option>{(data?.clients??[]).map((client)=><option key={client.id} value={client.id}>{clientName(client.id)}{client.user_id?"":" (not linked to login)"}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Related project (optional)</span><select value={projectId} onChange={(e)=>setProjectId(e.target.value)} className={field}><option value="">No related project</option>{clientProjects.map((project)=><option key={project.id} value={project.id}>{project.name}</option>)}</select></label><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="text-xs font-semibold text-slate-700">Service type</span><select value={serviceType} onChange={(e)=>setServiceType(e.target.value)} className={field}><option value="hosting">Hosting</option><option value="maintenance">Maintenance</option><option value="domain">Domain</option><option value="application_support">Application support</option><option value="branding">Brand support</option><option value="technical_support">Technical support</option><option value="custom">Custom service</option></select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Status</span><select value={serviceStatus} onChange={(e)=>setServiceStatus(e.target.value)} className={field}><option value="pending">Pending</option><option value="active">Active</option><option value="paused">Paused</option></select></label></div><label className="block"><span className="text-xs font-semibold text-slate-700">Service name</span><input required minLength={2} maxLength={160} value={serviceName} onChange={(e)=>setServiceName(e.target.value)} className={field} placeholder="e.g. Managed hosting plan"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Description (optional)</span><textarea maxLength={2000} rows={2} value={serviceDescription} onChange={(e)=>setServiceDescription(e.target.value)} className={textarea}/></label><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="text-xs font-semibold text-slate-700">Start date</span><input type="date" value={serviceStart} onChange={(e)=>setServiceStart(e.target.value)} className={field}/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Renewal date</span><input type="date" value={serviceRenewal} onChange={(e)=>setServiceRenewal(e.target.value)} className={field}/></label></div><label className="block"><span className="text-xs font-semibold text-slate-700">Currency (optional)</span><select value={currency} onChange={(e)=>setCurrency(e.target.value)} className={field}><option value="ZMW">ZMW</option><option value="USD">USD</option></select></label><button disabled={saving||!data?.servicesAvailable||!clientId} className={button}>{saving?<Loader2 className="h-4 w-4 animate-spin"/>:<Plus className="h-4 w-4"/>} Assign service</button>{!data?.servicesAvailable&&<p className="text-[10px] leading-5 text-amber-800">Service records are disabled until the workspace migration is applied in this environment.</p>}</form>}
     {tab==="milestone"&&<form onSubmit={submitMilestone} className="space-y-4"><div><h3 className="text-sm font-bold text-slate-800">Add a project milestone</h3><p className="mt-1 text-xs text-slate-500">Milestones can be shared for client review and approval.</p></div><label className="block"><span className="text-xs font-semibold text-slate-700">Project</span><select required value={projectId} onChange={(e)=>setProjectId(e.target.value)} className={field}><option value="">Choose a project</option>{(data?.projects??[]).map((project)=><option key={project.id} value={project.id}>{project.name} · {clientName(project.client_id)}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Milestone title</span><input required minLength={2} maxLength={180} value={milestoneTitle} onChange={(e)=>setMilestoneTitle(e.target.value)} className={field} placeholder="e.g. Initial concepts ready for review"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Description (optional)</span><textarea rows={2} maxLength={2000} value={milestoneDescription} onChange={(e)=>setMilestoneDescription(e.target.value)} className={textarea}/></label><div className="grid gap-3 sm:grid-cols-2"><label className="block"><span className="text-xs font-semibold text-slate-700">Status</span><select value={milestoneStatus} onChange={(e)=>setMilestoneStatus(e.target.value)} className={field}><option value="pending">Pending</option><option value="in_progress">In progress</option><option value="ready_for_review">Ready for review</option><option value="blocked">Blocked</option></select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Target date</span><input type="date" value={milestoneDue} onChange={(e)=>setMilestoneDue(e.target.value)} className={field}/></label></div><label className="block"><span className="text-xs font-semibold text-slate-700">Sort order</span><input type="number" min="0" max="10000" value={milestoneOrder} onChange={(e)=>setMilestoneOrder(e.target.value)} className={field}/></label><button disabled={saving||!data?.milestonesAvailable||!projectId} className={button}>{saving?<Loader2 className="h-4 w-4 animate-spin"/>:<Plus className="h-4 w-4"/>} Add milestone</button>{!data?.milestonesAvailable&&<p className="text-[10px] leading-5 text-amber-800">Milestone records are disabled until the workspace migration is applied in this environment.</p>}</form>}
     {tab==="deliverable"&&<form onSubmit={submitDeliverable} className="space-y-4"><div><h3 className="text-sm font-bold text-slate-800">Share a deliverable</h3><p className="mt-1 text-xs text-slate-500">Upload a private file and make it available in the client portal.</p></div><label className="block"><span className="text-xs font-semibold text-slate-700">Project</span><select required value={projectId} onChange={(e)=>{setProjectId(e.target.value);setDeliverableMilestone("")}} className={field}><option value="">Choose a project</option>{(data?.projects??[]).map((project)=><option key={project.id} value={project.id}>{project.name} · {clientName(project.client_id)}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Milestone (optional)</span><select value={deliverableMilestone} onChange={(e)=>setDeliverableMilestone(e.target.value)} className={field}><option value="">Not tied to a milestone</option>{projectMilestones.map((milestone)=><option key={milestone.id} value={milestone.id}>{milestone.title}</option>)}</select></label><label className="block"><span className="text-xs font-semibold text-slate-700">Deliverable title</span><input required minLength={2} maxLength={180} value={deliverableTitle} onChange={(e)=>setDeliverableTitle(e.target.value)} className={field} placeholder="e.g. Brand guidelines — review copy"/></label><label className="block"><span className="text-xs font-semibold text-slate-700">Description (optional)</span><textarea rows={2} maxLength={2000} value={deliverableDescription} onChange={(e)=>setDeliverableDescription(e.target.value)} className={textarea}/></label><label className="block"><span className="text-xs font-semibold text-slate-700">File</span><input id="admin-deliverable-file" type="file" required onChange={(e:ChangeEvent<HTMLInputElement>)=>setDeliverableFile(e.target.files?.[0]??null)} accept=".png,.jpg,.jpeg,.webp,.svg,.pdf,.zip,.txt,.md,.json,.bin" className="mt-1.5 block w-full rounded-xl border border-slate-200 px-3 py-3 text-[10px] file:mr-3 file:rounded-lg file:border-0 file:bg-slate-100 file:px-3 file:py-2 file:text-[10px] file:font-bold"/></label><button disabled={saving||!data?.deliverablesAvailable||!projectId||!deliverableFile} className={button}>{saving?<Loader2 className="h-4 w-4 animate-spin"/>:<UploadCloud className="h-4 w-4"/>} Upload and share</button>{!data?.deliverablesAvailable&&<p className="text-[10px] leading-5 text-amber-800">Deliverables are disabled until the workspace migration is applied in this environment.</p>}</form>}
    </div>
   </section>
  </div>
  <div className="flex items-start gap-3 rounded-xl border border-slate-200 bg-white p-4"><ShieldCheck className="mt-0.5 h-4 w-4 shrink-0 text-teal"/><p className="text-xs leading-5 text-slate-600">Admin actions are checked server-side. A project or service becomes visible to a client only when it is linked to the correct authenticated customer record. Do not link a client record to an account without verifying the account owner.</p></div>
 </div>
   </div>
  </details>
 </div>
}
